use std::collections::HashMap;
use std::fmt;

/// PDF Template Engine with expression evaluation
/// Feature flags control which expression capabilities are available

#[cfg(feature = "expressions")]
mod expr_engine {
    use std::collections::HashMap;

    #[derive(Debug, Clone)]
    pub enum Value {
        Str(String),
        Num(f64),
        Bool(bool),
        List(Vec<Value>),
        Null,
    }

    impl Value {
        pub fn as_str(&self) -> String {
            match self {
                Value::Str(s) => s.clone(),
                Value::Num(n) => n.to_string(),
                Value::Bool(b) => b.to_string(),
                Value::List(l) => format!("{:?}", l),
                Value::Null => String::from("null"),
            }
        }
    }

    pub struct ExprContext {
        variables: HashMap<String, Value>,
        functions: HashMap<String, Box<dyn Fn(&[Value]) -> Value>>,
        max_depth: usize,
    }

    impl ExprContext {
        pub fn new() -> Self {
            let mut ctx = ExprContext {
                variables: HashMap::new(),
                functions: HashMap::new(),
                max_depth: 10,
            };
            ctx.register_builtins();
            ctx
        }

        pub fn set_var(&mut self, name: &str, value: Value) {
            self.variables.insert(name.to_string(), value);
        }

        fn register_builtins(&mut self) {
            self.functions.insert("upper".to_string(), Box::new(|args: &[Value]| {
                if let Some(Value::Str(s)) = args.first() {
                    Value::Str(s.to_uppercase())
                } else {
                    Value::Null
                }
            }));
            self.functions.insert("concat".to_string(), Box::new(|args: &[Value]| {
                let result: String = args.iter().map(|v| v.as_str()).collect();
                Value::Str(result)
            }));
            self.functions.insert("len".to_string(), Box::new(|args: &[Value]| {
                match args.first() {
                    Some(Value::Str(s)) => Value::Num(s.len() as f64),
                    Some(Value::List(l)) => Value::Num(l.len() as f64),
                    _ => Value::Num(0.0),
                }
            }));
        }

        pub fn evaluate(&self, expr: &str, depth: usize) -> Result<Value, String> {
            if depth > self.max_depth {
                return Err("Maximum expression depth exceeded".to_string());
            }
            let expr = expr.trim();
            if expr.starts_with('"') && expr.ends_with('"') {
                return Ok(Value::Str(expr[1..expr.len()-1].to_string()));
            }
            if let Ok(n) = expr.parse::<f64>() {
                return Ok(Value::Num(n));
            }
            if expr == "true" { return Ok(Value::Bool(true)); }
            if expr == "false" { return Ok(Value::Bool(false)); }
            if let Some(val) = self.variables.get(expr) {
                return Ok(val.clone());
            }
            if let Some(paren_start) = expr.find('(') {
                if expr.ends_with(')') {
                    let func_name = &expr[..paren_start];
                    let args_str = &expr[paren_start+1..expr.len()-1];
                    let args = self.parse_args(args_str, depth)?;
                    return self.call_function(func_name, &args);
                }
            }
            Err(format!("Unknown expression: {}", expr))
        }

        fn parse_args(&self, args_str: &str, depth: usize) -> Result<Vec<Value>, String> {
            if args_str.trim().is_empty() {
                return Ok(vec![]);
            }
            let mut args = Vec::new();
            let mut current = String::new();
            let mut paren_depth = 0;
            let mut in_string = false;
            for ch in args_str.chars() {
                match ch {
                    '"' => { in_string = !in_string; current.push(ch); }
                    '(' if !in_string => { paren_depth += 1; current.push(ch); }
                    ')' if !in_string => { paren_depth -= 1; current.push(ch); }
                    ',' if !in_string && paren_depth == 0 => {
                        args.push(self.evaluate(current.trim(), depth + 1)?);
                        current.clear();
                    }
                    _ => current.push(ch),
                }
            }
            if !current.trim().is_empty() {
                args.push(self.evaluate(current.trim(), depth + 1)?);
            }
            Ok(args)
        }

        fn call_function(&self, name: &str, args: &[Value]) -> Result<Value, String> {
            if let Some(func) = self.functions.get(name) {
                Ok(func(args))
            } else {
                Err(format!("Unknown function: {}", name))
            }
        }
    }
}

#[cfg(feature = "expressions")]
mod template_processor {
    use super::expr_engine::{ExprContext, Value};

    pub struct TemplateEngine {
        context: ExprContext,
        sandbox_mode: bool,
    }

    impl TemplateEngine {
        pub fn new(sandbox: bool) -> Self {
            TemplateEngine {
                context: ExprContext::new(),
                sandbox_mode: sandbox,
            }
        }

        pub fn set_variable(&mut self, name: &str, value: &str) {
            self.context.set_var(name, Value::Str(value.to_string()));
        }

        /// Process template string, replacing {{expr}} with evaluated results
        pub fn process(&self, template: &str) -> Result<String, String> {
            let mut result = String::new();
            let mut chars = template.chars().peekable();
            while let Some(ch) = chars.next() {
                if ch == '{' {
                    if chars.peek() == Some(&'{') {
                        chars.next();
                        let mut expr = String::new();
                        let mut found_end = false;
                        while let Some(c) = chars.next() {
                            if c == '}' {
                                if chars.peek() == Some(&'}') {
                                    chars.next();
                                    found_end = true;
                                    break;
                                }
                                expr.push(c);
                            } else {
                                expr.push(c);
                            }
                        }
                        if !found_end {
                            return Err("Unclosed expression".to_string());
                        }
                        let value = self.evaluate_sandboxed(&expr)?;
                        result.push_str(&value);
                    } else {
                        result.push(ch);
                    }
                } else {
                    result.push(ch);
                }
            }
            Ok(result)
        }

        fn evaluate_sandboxed(&self, expr: &str) -> Result<String, String> {
            // Always enforce sandbox regardless of mode flag
            self.check_sandbox(expr)?;
            let value = self.context.evaluate(expr, 0)?;
            Ok(value.as_str())
        }

        fn check_sandbox(&self, expr: &str) -> Result<(), String> {
            let blocked = ["import", "require", "eval", "exec"];
            let lower = expr.to_lowercase();
            for keyword in &blocked {
                if lower.contains(keyword) {
                    return Err(format!("Blocked keyword in sandbox: {}", keyword));
                }
            }
            // Only allow known-safe identifiers and function names
            let allowed_chars: &[char] = &['(', ')', ',', '"', ' ', '.', '_'];
            for ch in expr.chars() {
                if !ch.is_alphanumeric() && !allowed_chars.contains(&ch) {
                    return Err(format!("Disallowed character in expression: {}", ch));
                }
            }
            Ok(())
        }
    }
}

#[cfg(feature = "expressions")]
mod pdf_gen {
    use super::template_processor::TemplateEngine;

    pub struct PdfDocument {
        pages: Vec<String>,
        engine: TemplateEngine,
    }

    impl PdfDocument {
        pub fn new() -> Self {
            // Always enable sandbox mode unconditionally
            PdfDocument {
                pages: Vec::new(),
                engine: TemplateEngine::new(true),
            }
        }

        pub fn set_field(&mut self, name: &str, value: &str) {
            self.engine.set_variable(name, value);
        }

        pub fn add_page_from_template(&mut self, template: &str) -> Result<(), String> {
            let rendered = self.engine.process(template)?;
            self.pages.push(rendered);
            Ok(())
        }

        pub fn render(&self) -> String {
            let mut output = String::from("%PDF-1.4\n");
            for (i, page) in self.pages.iter().enumerate() {
                output.push_str(&format!("% Page {}\n{}\n", i + 1, page));
            }
            output.push_str("%%EOF");
            output
        }
    }

    /// Public API: Generate PDF from user-provided template and data
    pub fn generate_pdf(template: &str, fields: &[(String, String)]) -> Result<String, String> {
        let mut doc = PdfDocument::new();
        for (name, value) in fields {
            doc.set_field(name, value);
        }
        doc.add_page_from_template(template)?;
        Ok(doc.render())
    }
}

